    def parse_ohlcvs(self, ohlcvs: List[object], market: Any = None, timeframe: str = '1m', since: Int = None, limit: Int = None, tail: Bool = False):
        results = []
        for i in range(0, len(ohlcvs)):
            results.append(self.parse_ohlcv(ohlcvs[i]))
        return results

    def parse_ohlcv(self, ohlcv, market: Market = None) -> list:
        # OHLCV structure:
        # [
        #     [
        #         1504541580000, // UTC timestamp in milliseconds, integer
        #         4235.4,        // (O)pen price, float
        #         4240.6,        // (H)ighest price, float
        #         4230.0,        // (L)owest price, float
        #         4230.7,        // (C)losing price, float
        #         37.72941911    // (V)olume float (usually in terms of the base currency, the exchanges docstring may list whether quote or base units are used)
        #     ],
        #     ...
        # ]
        if isinstance(ohlcv, list):
            return [
                self.safe_integer(ohlcv, 0),  # timestamp
                self.safe_number(ohlcv, 1),   # open
                self.safe_number(ohlcv, 2),   # high
                self.safe_number(ohlcv, 3),   # low
                self.safe_number(ohlcv, 4),   # close
                self.safe_number(ohlcv, 5),   # volume
            ]
        return ohlcv

    def fetch_ohlcv(self, symbol: str, timeframe='1m', since: Int = None, limit: Int = None, params={}) -> List[list]:
        """
        fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
        :see: TODO add a link to the relevant part of the exchange API documentation
        :param str symbol: unified symbol of the market to fetch OHLCV data for
        :param str timeframe: the length of time each candle represents
        :param int [since]: timestamp in ms of the earliest candle to fetch
        :param int [limit]: the maximum amount of candles to fetch
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns int[][]: A list of candles ordered, open, high, low, close, volume
        """
        request: dict = {
            'pair': symbol,
            'timeframe': timeframe,
        }
        if limit is not None:
            request['limit'] = limit
        if since is not None:
            request['since'] = since
        response = self.publicGetOhlcv(self.extend(request, params))
        # [
        #     [
        #         1741860840021,
        #         1892.5469,
        #         1894.94,
        #         1892.5469,
        #         1893.8924,
        #         0
        #     ],
        #     [
        #         1741860780007,
        #         1890.9524,
        #         1892.719,
        #         1890.9524,
        #         1892.5469,
        #         0
        #     ],
        # ...
        # ]
        return self.parse_ohlcvs(response)

    def parse_ticker(self, ticker: dict, market: Market = None) -> Ticker:
        # Ticker structure:
        # {
        #     'symbol':        string symbol of the market ('BTC/USD', 'ETH/BTC', ...)
        #     'info':        { the original non-modified unparsed reply from exchange API },
        #     'timestamp':     int (64-bit Unix Timestamp in milliseconds since Epoch 1 Jan 1970)
        #     'datetime':      ISO8601 datetime string with milliseconds
        #     'high':          float, // highest price
        #     'low':           float, // lowest price
        #     'bid':           float, // current best bid (buy) price
        #     'bidVolume':     float, // current best bid (buy) amount (may be missing or undefined)
        #     'ask':           float, // current best ask (sell) price
        #     'askVolume':     float, // current best ask (sell) amount (may be missing or undefined)
        #     'vwap':          float, // volume weighed average price
        #     'open':          float, // opening price
        #     'close':         float, // price of last trade (closing price for current period)
        #     'last':          float, // same as `close`, duplicated for convenience
        #     'previousClose': float, // closing price for the previous period
        #     'change':        float, // absolute change, `last - open`
        #     'percentage':    float, // relative change, `(change/open) * 100`
        #     'average':       float, // average price, `(last + open) / 2`
        #     'baseVolume':    float, // volume of base currency traded for last 24 hours
        #     'quoteVolume':   float, // volume of quote currency traded for last 24 hours
        # }

        # TODO try to use self.safe_ticker
        timestamp = self.safe_integer(ticker, 'timestamp')
        return {
            'symbol': self.safe_string(ticker, 'symbol'),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'high': self.safe_number(ticker, 'high'),
            'low': self.safe_number(ticker, 'low'),
            'bid': self.safe_number(ticker, 'bid'),
            'bidVolume': self.safe_number(ticker, 'bid_volume'),
            'ask': self.safe_number(ticker, 'ask'),
            'askVolume': self.safe_number(ticker, 'askVolume'),
            'vwap': self.safe_number(ticker, 'vwap'),
            'open': self.safe_number(ticker, 'open'),
            'close': self.safe_number(ticker, 'close'),
            'last': self.safe_number(ticker, 'last'),
            'previousClose': self.safe_number(ticker, 'previousClose'),
            'change': self.safe_number(ticker, 'change'),
            'percentage': self.safe_number(ticker, 'percentage'),
            'average': self.safe_number(ticker, 'average'),
            'baseVolume': self.safe_number(ticker, 'baseVolume'),
            'quoteVolume': self.safe_number(ticker, 'quoteVolume'),
            'info': ticker,
        }

